def hero(vid,eb,title,em,lede,ctas=None,crumb=''):
    ctas=ctas or [('index.html#enrol','Enrol now','btn-gold'),('index.html#level','Find my level','btn-line')]
    return f'''<section class="ch">{V(vid,P)}<div class="tint"></div><div class="w"><div class="glass"><div class="crumbs"><a href="index.html">Club Italia</a> / {crumb or E(eb)}</div><span class="eb" style="color:var(--oro2)">{E(eb)}</span>
<h1 data-split>{title} <em>{em}</em></h1><p class="lede">{lede}</p><div style="display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.4rem">{''.join(f'<a class="btn {c}" href="{u}">{t}</a>' for u,t,c in ctas)}</div></div></div></section>'''
def sechead(eb,t,em,p=''): return f'<div class="head rv"><span class="eb">{eb}</span><h2 data-split>{t} <em>{em}</em></h2>{f"<p>{p}</p>" if p else ""}</div>'
BAND=lambda t,em,p: f'<section class="band">{V("ag-cypress-road",P)}<div class="tint"></div><span class="frame"></span><div class="w rv"><h2 data-split>{t} <em>{em}</em></h2><p>{p}</p><a class="btn btn-gold" href="index.html#enrol">Begin your journey <span class="arr">→</span></a></div></section>'
def page(fn,title,desc,body): open(fn,'w').write(fix(head(title,desc,P)+body+foot(P)))
def hrs(k):
    c=CO[k][0];n=20 if c!='cap' else 6;m=85 if c!='cap' else 60;t=n*m;return f'{t//60} h {t%60:02d}' if t%60 else f'{t//60} h'
